/*
 * A158069  Primes p such that sum of digits of p - first digit of p is not
 *          prime.
 * https://oeis.org/A158069
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, less
 * Formula:   not stated
 * Range:     u8 n <= 35, u16 n <= 56, u32 n <= 56, u64 n <= 56, u128 n <= 56,
 *            big any n
 * Helpers:   digit_sum, is_prime, is_prime_small
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Function computes the n‑th prime p such that
 *   sum_of_digits(p) – first_digit(p) is NOT prime.
 * The sequence is generated by testing successive primes;
 * results are memoised so calls may be in any order. */
#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include "../utils/is_prime.h"
#include "../utils/digit_sum.h"
#include "../utils/is_prime_small.h"

static seq_t *cache      = NULL;  /* stored sequence values */
static size_t cache_cap  = 0;     /* allocated capacity of cache   */
static size_t cache_cnt  = 0;     /* number of values actually stored */
static idx_t  next_candidate = 2; /* next integer to test */

/* Extends cache allocation to hold at least `need` elements. */
static void grow_cache(size_t need)
{
    if (need <= cache_cap) return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < need) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) abort();                 /* allocation failure */
    cache     = tmp;
    cache_cap = new_cap;
}

/* Returns true iff p is a prime satisfying the digit‑sum condition. */
static bool good_prime(idx_t p)
{
    seq_t   val   = (seq_t)p;
    seq_t   sum   = digit_sum(val);
    seq_t   first = val;
    while (first >= 10) first /= 10;    /* extract the leading digit */
    seq_t   diff = sum - first;         /* difference (may be 0) */
    return !is_prime_small(diff);       /* diff must NOT be prime */
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for index 0, guard */

    /* Generate more terms if required. */
    while (cache_cnt < n) {
        /* Find next prime candidate. */
        while (!is_prime(next_candidate)) ++next_candidate;

        /* Check the digit‑sum condition. */
        if (good_prime(next_candidate)) {
            grow_cache(cache_cnt + 1);
            cache[cache_cnt] = (seq_t)next_candidate;
            ++cache_cnt;
        }
        ++next_candidate;          /* move to next integer */
    }

    return cache[n - 1];
}
